declarations.code:
template <

    class Key,

    class Compare = std::less<Key>,

    class KeyContainer = std::vector<Key>

    >
class flat_set;

examples.code:
#include <flat_set>
#include <vector>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::flat_set<int> values;
    values.insert(2);
    values.emplace(1);
    values.emplace_hint(values.end(), 3);
    assert(values.count(2) == 1 && values.lower_bound(2) != values.end() &&
        values.upper_bound(2) != values.begin());
    std::flat_set<int> copy = values;
    assert(copy == values);
    copy.swap(values);
    std::swap(copy, values);
    std::flat_set deduced(std::vector<int>{1, 2});
    assert(deduced.size() == 2);
    std::flat_set<int> sorted{std::sorted_unique, std::vector<int>{1, 2}};
    assert(sorted.size() == 2);
}
